  trip: {title:'Trip Planner',intro:'A group trip planning prototype for turning scattered conversations into a shared plan.',image:'assets/trip-dashboard.png',alt:'Trip Planner calendar with fictional demo trip data',tags:['React','Supabase','Calendar','Group planning'],story:'Dates, meeting points, itineraries, expenses, and packing details can be hard to keep together. Trip Planner organizes those details around a calendar and a guided trip workflow.',approach:'The interface includes a five-step trip wizard and views for multi-day activities, group coordination, expenses, and checklists. React handles the interface with Supabase integrations for data and media.',status:'Portfolio/demo application. The committed screenshots use fictional intercepted API responses. Current authentication and live backend limitations are documented; this is not presented as a production service.',repo:'trip-planner'}
