const dialog = document.querySelector('#project-dialog');
const content = document.querySelector('#dialog-content');
let lastTrigger;
function openProject(key, trigger) {
  const p = projectData[key]; if (!p) return;
  lastTrigger = trigger;
  const {escape:esc,safeURL}=PortfolioCMS;
  const image=safeURL(p.image),repository=safeURL(p.repository_url||(p.repo?'https://github.com/Sanju2911/'+p.repo:'')),demo=safeURL(p.demo_url);
  content.innerHTML = `<h2 id="dialog-title">${esc(p.title)}</h2><p class="dialog-intro">${esc(p.intro)}</p><div class="tags">${(p.tags||[]).map(tag=>`<span>${esc(tag)}</span>`).join('')}</div>${image?`<img class="dialog-image" src="${esc(image)}" alt="${esc(p.alt||p.title)}">`:''}<div class="dialog-sections"><section><h3>The idea</h3><p>${esc(p.story)}</p></section><section><h3>How it fits together</h3><p>${esc(p.approach)}</p></section></div>${(p.gallery||[]).length?`<div class="dialog-gallery">${p.gallery.filter(g=>safeURL(g.url)).map(g=>`<figure><img loading="lazy" src="${esc(safeURL(g.url))}" alt="${esc(g.alt||p.title)}">${g.alt?`<figcaption>${esc(g.alt)}</figcaption>`:''}</figure>`).join('')}</div>`:''}<div class="dialog-links">${repository?`<a class="button dark" href="${esc(repository)}" target="_blank" rel="noopener noreferrer">Explore the repository <span>↗</span></a>`:''}${demo?`<a class="text-link" href="${esc(demo)}" target="_blank" rel="noopener noreferrer">${key==='pjtsau'?'Read completion certificate ↗':'View live project ↗'}</a>`:''}<button class="text-link" id="next-project" style="background:none;padding:8px 0">Next project →</button></div><p class="dialog-footnote">${esc(p.status)}</p>`;
  if (!dialog.open) dialog.showModal();
  dialog.scrollTop = 0;
  document.querySelector('#close-dialog').focus();
  document.querySelector('#next-project').addEventListener('click',()=>{const keys=Object.keys(projectData);openProject(keys[(keys.indexOf(key)+1)%keys.length],lastTrigger)});
}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>openProject(button.dataset.project,button)));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>lastTrigger?.focus());
document.querySelector('.art-switch').addEventListener('click',()=>{const art=document.querySelector('.hero-art');const colors=['#ded5f3','#dbead7','#f4d9c7','#f3e9b7'];let index=Number(art.dataset.color||0);index=(index+1)%colors.length;art.dataset.color=index;art.style.backgroundColor=colors[index];});
document.querySelector('#copy-email').addEventListener('click',async()=>{const button=document.querySelector('#copy-email');try{await navigator.clipboard.writeText('tadivaka.sathwik@gmail.com');button.innerHTML='Copied <span>✓</span>';const toast=document.querySelector('.toast');toast.textContent='Email copied. Say hello anytime.';toast.classList.add('visible');setTimeout(()=>{toast.classList.remove('visible');button.innerHTML='Copy email <span>⧉</span>';},2600);}catch{window.location.href='mailto:tadivaka.sathwik@gmail.com';}});
